_updatePlayer(dt) {
  const p = this.player, input = this.game.input;
  if (!p.alive) return;
  // look
  this.camYaw -= input.look.x;
  this.camPitch = clamp(this.camPitch + input.look.y * 0.85, -0.12, 0.72);

  p.crouch = damp(p.crouch, input.crouch ? 1 : 0, 8, dt);
  const wantSprint = input.sprint && !input.crouch && p.stam > 1;
  // direction
  const fx = Math.sin(this.camYaw), fz = Math.cos(this.camYaw);
  const rx = Math.cos(this.camYaw), rz = -Math.sin(this.camYaw);
  let mx = rx * input.move.x + fx * (-input.move.y);
  let mz = rz * input.move.x + fz * (-input.move.y);
  const mlen = Math.hypot(mx, mz);
  const moving = mlen > 0.05;
  if (moving) { mx/=mlen; mz/=mlen; }

  let speed = input.crouch ? 2.3 : wantSprint && moving ? 7.5 : 4.3;
  if (this.dodgeT > 0) speed = 0; // handled by dash
  ...
