361:   recordAct(n, data) { this.actStats[n] = { ...data }; }
362: 
363:   playerDied({ cause = 'Te alcanzó en la oscuridad.', eyebrow = 'Acto I', title = 'Has caído' }) {
364:     if (this.state === 'dead') return;
365:     this.state = 'dead';
366:     this.ui.hud.classList.remove('on');
367:     this.ui.bossbar.classList.remove('on');
