389:   _win() {
390:     this.state = 'win';
391:     this.ui.hud.classList.remove('on');
392:     this.ui.bossbar.classList.remove('on');
393:     this.ui.compass.classList.remove('on');
394:     this.audio.setAmbience({ rain: 0, wind: 0.06, drone: 0.03, engine: 0 });
395:     this.audio.setTension(0);
396:     const total = (this.actStats[1]?.time || 0) + (this.actStats[2]?.time || 0) + (this.actStats[3]?.time || 0);
397:     if (!this.bestTime || total < this.bestTime) {
398:       this.bestTime = total;
399:       localStorage.setItem('uc_best', String(total));
400:     }
401:     const fmt = (t) => `${Math.floor(t / 60)}:${String(Math.floor(t % 60)).padStart(2, '0')}`;
402:     const dmg = this.actStats[1]?.damage || 0;
403:     this.ui.winSub.textContent = 'El Segador ya no volverá a levantarse. La ciudad es tuya hasta el amanecer.';
404:     this.ui.winStats.innerHTML = `
405:       <div class="stat"><b>${fmt(total)}</b><span>Tiempo total</span></div>
406:       <div class="stat"><b>${Math.round(dmg)}</b><span>Daño recibido</span></div>
407:       <div class="stat"><b>2.4 km</b><span>Carretera</span></div>
408:       <div class="stat"><b>III / III</b><span>Actos</span></div>`;
409:     this.ui.win.classList.remove('hidden');
410:     this.audio.win();
411:   }
412: 
413:   /* ---------------- loop ---------------- */
414:   _frame() {
415:     const raw = this.clock.getDelta();
416:     const dt = Math.min(raw, 0.05);
417:     this.input.update();
418:     this.audio.update(dt);
419: 
420:     if (this._toastTimer > 0) {
421:       this._toastTimer -= dt;
422:       if (this._toastTimer <= 0) this.ui.toast.classList.remove('on');
423:     }
424: 
425:     if (this.state === 'playing' && this.act) {
426:       this.elapsed += dt;
427:       this.actTime += dt;
428:       this.act.update(dt);
429:     } else if (this.state === 'title' || this.state === 'story') {
430:       this._updatePreview(dt);
431:     }
432: 
433:     this.input.endFrame();
434: 
435:     if (this.state === 'title' || this.state === 'story' || this.state === 'loading') {
436:       this.renderer.render(this.previewScene || this.scene, this.camera);
437:     } else {
438:       this.renderer.render(this.act?.scene || this.scene, this.camera);
439:     }
440:   }
441: 
442:   _updatePreview(dt) {
443:     this._previewT += dt;
444:     const t = this._previewT * 0.045;
445:     this.camera.position.set(Math.cos(t) * 26, 9 + Math.sin(t * 0.7) * 2, Math.sin(t) * 26);
446:     this.camera.lookAt(0, 4, 0);
447:     this.camera.fov = 55;
448:     this.camera.updateProjectionMatrix();
449:     if (this.previewScene) {
450:       const amber = this.previewScene.children.find((c) => c.isPointLight);
451:       if (amber) amber.intensity = 45 + Math.sin(this._previewT * 2.2) * 12;
452:     }
453:   }
454: }
