11:   let t0 = 0, t1 = 1;
12:   const dx = x2 - x1, dz = z2 - z1;
13:   if (Math.abs(dx) < 1e-6) {
14:     if (x1 < b.minX || x1 > b.maxX) return false;
15:   } else {
16:     let ta = (b.minX - x1) / dx, tb = (b.maxX - x1) / dx;
17:     if (ta > tb) [ta, tb] = [tb, ta];
18:     t0 = Math.max(t0, ta); t1 = Math.min(t1, tb);
19:     if (t0 > t1) return false;
20:   }
21:   if (Math.abs(dz) < 1e-6) {
22:     if (z1 < b.minZ || z1 > b.maxZ) return false;
23:   } else {
24:     let ta = (b.minZ - z1) / dz, tb = (b.maxZ - z1) / dz;
25:     if (ta > tb) [ta, tb] = [tb, ta];
26:     t0 = Math.max(t0, ta); t1 = Math.min(t1, tb);
27:     if (t0 > t1) return false;
28:   }
29:   return t1 > 0.015 && t0 < 0.985;
30: }
