217:   _house(x, z, w, d, h, wall, roof, lit) {
218:     const g = new THREE.Group();
219:     const wallMat = new THREE.MeshStandardMaterial({ color: wall, roughness: 0.95, flatShading: true });
220:     const roofMat = new THREE.MeshStandardMaterial({ color: roof, roughness: 1, flatShading: true });
221:     const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), wallMat);
222:     body.position.y = h / 2;
223:     body.castShadow = body.receiveShadow = true;
224:     g.add(body);
225: 
226:     const roofMesh = new THREE.Mesh(new THREE.ConeGeometry(Math.hypot(w, d) * 0.63, h * 0.5, 4), roofMat);
227:     roofMesh.position.y = h + h * 0.25;
228:     roofMesh.rotation.y = Math.PI / 4;
229:     roofMesh.scale.set(w / Math.max(w, d), 1, d / Math.max(w, d));
230:     roofMesh.castShadow = true;
231:     g.add(roofMesh);
232: 
233:     const winMatLit = new THREE.MeshStandardMaterial({ color: 0x2a1a0c, emissive: 0xffa64d, emissiveIntensity: 1.9, roughness: 0.6 });
234:     const winMatDark = new THREE.MeshStandardMaterial({ color: 0x0c1116, roughness: 0.3, metalness: 0.6 });
235:     const frameMat = new THREE.MeshStandardMaterial({ color: 0x14100d, roughness: 1 });
236:     const addWindow = (px, py, pz, ry) => {
237:       const fr = new THREE.Mesh(new THREE.BoxGeometry(1.25, 1.4, 0.1), frameMat);
238:       fr.position.set(px, py, pz);
239:       fr.rotation.y = ry;
240:       g.add(fr);
241:       const wm = new THREE.Mesh(new THREE.BoxGeometry(1.0, 1.12, 0.12), lit ? winMatLit : winMatDark);
242:       wm.position.set(px, py, pz);
243:       wm.rotation.y = ry;
244:       g.add(wm);
245:       if (lit) {
246:         const gl = makeGlow(0xffa851, 2.4, 0.24);
247:         gl.position.set(px + Math.sin(ry) * 0.12, py, pz + Math.cos(ry) * 0.12);
248:         g.add(gl);
249:       }
250:     };
251:     const fy = h * 0.58;
252:     addWindow(-w * 0.24, fy, d / 2 + 0.02, 0);
253:     addWindow(w * 0.24, fy, d / 2 + 0.02, 0);
254:     if (w > 8) {
255:       addWindow(-w * 0.24, fy, -d / 2 - 0.02, Math.PI);
256:       addWindow(w * 0.24, fy, -d / 2 - 0.02, Math.PI);
257:     }
258:     addWindow(w / 2 + 0.02, fy, 0, Math.PI / 2);
259: 
260:     const door = new THREE.Mesh(new THREE.BoxGeometry(1.1, 2.1, 0.12), new THREE.MeshStandardMaterial({ color: 0x16110c, roughness: 1 }));
261:     door.position.set(0, 1.05, d / 2 + 0.03);
262:     g.add(door);
263:     const step = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.18, 0.7), new THREE.MeshStandardMaterial({ color: 0x2f2c26, roughness: 1 }));
264:     step.position.set(0, 0.09, d / 2 + 0.35);
265:     step.receiveShadow = true;
266:     g.add(step);
267: 
268:     if (lit) {
269:       const lamp = new THREE.PointLight(0xffa552, 7, 11, 2);
270:       lamp.position.set(0, 2.6, d / 2 + 0.8);
271:       g.add(lamp);
272:     }
273: 
274:     g.position.set(x, 0, z);
275:     g.rotation.y = rand(-0.045, 0.045);
276:     this.scene.add(g);
277:   }
