565: Act1.prototype._moveWithCollision = function (obj, dx, dz, radius = 0.42) {
566:   const ox = obj.x, oz = obj.z;
567:   let nx = clamp(ox + dx, -BOUND, BOUND), nz = clamp(oz + dz, -BOUND, BOUND);
568:   for (const b of this.colliders) {
569:     if (nx + radius > b.minX && nx - radius < b.maxX && nz + radius > b.minZ && nz - radius < b.maxZ) {
570:       if (!(ox + radius > b.minX && ox - radius < b.maxX && oz + radius > b.minZ && oz - radius < b.maxZ)) {
571:         if (ox + radius <= b.minX || ox - radius >= b.maxX) nx = ox;
572:         if (oz + radius <= b.minZ || oz - radius >= b.maxZ) nz = oz;
