552: Act1.prototype._updateCamera = function (dt, snap = false) {
553:   const p = this.player.pos;
554:   const desired = new THREE.Vector3(
555:     p.x - Math.sin(this.camYaw) * this.camDist,
556:     p.y + 3.1 + this.camPitch * 3,
557:     p.z - Math.cos(this.camYaw) * this.camDist,
558:   );
559:   this.camPos.lerp(desired, snap ? 1 : 1 - Math.exp(-7 * dt));
560:   this.camLook.set(p.x, p.y + 1.25, p.z);
561:   this.game.camera.position.copy(this.camPos);
562:   this.game.camera.lookAt(this.camLook);
563: };
