579: Act1.prototype._hurt = function (amount) {
580:   if (this.invuln > 0 || !this.player.alive) return;
581:   this.player.hp = Math.max(0, this.player.hp - amount);
582:   this.damageTaken += amount;
583:   this.invuln = 1.15;
584:   this.hurtTimer = 0.45;
585:   this.shake = 0.34;
586:   this.game.damageFlash();
587:   this.game.audio.hit();
588:   this.player.knock.set(this.player.pos.x - this.killer.pos.x, 0, this.player.pos.z - this.killer.pos.z).normalize().multiplyScalar(5.5);
589:   if (this.player.hp <= 0) {
590:     this.player.alive = false;
591:     this.game.playerDied({ cause: 'El Segador te alcanzó antes de llegar al coche.', eyebrow: 'Acto I · La huida', title: 'Te encontró' });
592:   }
593: };
