595: Act1.prototype._attack = function () {
596:   if (this.dodgeT > 0 || this.dodgeCD > 0 || this.player.stam < 24) return;
597:   this.player.stam -= 24;
598:   this.dodgeCD = 0.72;
599:   this.dodgeT = 0.28;
600:   const i = this.game.input;
601:   const forward = new THREE.Vector3(Math.sin(this.player.yaw), 0, Math.cos(this.player.yaw));
602:   const side = new THREE.Vector3(forward.z, 0, -forward.x);
603:   this.dodgeDir.copy(forward).multiplyScalar(-i.move.y || 1).addScaledVector(side, i.move.x).normalize();
604:   if (this.dodgeDir.lengthSq() < 0.1) this.dodgeDir.copy(forward);
605:   this.invuln = Math.max(this.invuln, 0.38);
606:   this.game.audio.dodge?.();
607: };
