316:   _buildTrees() {
317:     const count = 210;
318:     const trunkGeo = new THREE.CylinderGeometry(0.16, 0.24, 2.4, 5);
319:     const trunkMat = new THREE.MeshStandardMaterial({ color: 0x191410, roughness: 1, flatShading: true });
320:     const leafGeo = new THREE.ConeGeometry(1.5, 4.4, 6);
321:     const leafMat = new THREE.MeshStandardMaterial({ color: 0x0f1a15, roughness: 1, flatShading: true });
322:     const trunks = new THREE.InstancedMesh(trunkGeo, trunkMat, count);
323:     const leaves = new THREE.InstancedMesh(leafGeo, leafMat, count);
324:     trunks.castShadow = leaves.castShadow = true;
325:     const m = new THREE.Matrix4(), q = new THREE.Quaternion(), p = new THREE.Vector3(), sc = new THREE.Vector3();
326:     for (let i = 0; i < count; i++) {
327:       let x, z;
328:       if (i < 150) {
329:         const a = rand(0, TAU), r = rand(78, 135);
330:         x = Math.cos(a) * r; z = Math.sin(a) * r;
331:       } else {
332:         const a = rand(0, TAU), r = rand(34, 76);
333:         x = Math.cos(a) * r; z = Math.sin(a) * r;
334:         if (Math.abs(z) < 22) { x = pick([-1, 1]) * rand(30, 80); z = pick([-1, 1]) * rand(26, 60); }
335:       }
336:       const s = rand(0.8, 1.6);
337:       p.set(x, 1.2 * s, z);
338:       sc.set(s, s, s);
339:       q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), rand(0, TAU));
340:       m.compose(p, q, sc);
341:       trunks.setMatrixAt(i, m);
342:       p.set(x, 3.3 * s, z);
343:       m.compose(p, q, sc);
344:       leaves.setMatrixAt(i, m);
345:     }
346:     this.scene.add(trunks, leaves);
347:   }
