609: Act1.prototype._updateKiller = function (dt) {
610:   const k = this.killer, p = this.player.pos;
611:   const dist = flatDist(k.pos, p);
612:   const sees = dist < 27 && (dist < 10 || Math.random() > 0.003);
613:   if (sees) {
614:     k.state = 'chase'; k.loseT = 0;
615:     if (!k.seen) { k.seen = true; this.game.toast('Te ha visto', '¡Corre!'); this.alerted = true; }
616:     k.target.copy(p);
617:   } else if (k.state === 'chase') {
618:     k.loseT += dt;
619:     if (k.loseT > 4.5) { k.state = 'patrol'; k.seen = false; }
620:   }
621:   if (k.state === 'patrol') {
622:     const waypoint = k.patrol[k.patrolI];
623:     if (flatDist(k.pos, waypoint) < 2.4) k.patrolI = (k.patrolI + 1) % k.patrol.length;
624:     k.target.copy(k.patrol[k.patrolI]);
625:   }
626:   const dx = k.target.x - k.pos.x, dz = k.target.z - k.pos.z;
627:   const desiredYaw = Math.atan2(dx, dz);
628:   k.yaw = dampAngle(k.yaw, desiredYaw, 4.5, dt);
629:   k.group.rotation.y = k.yaw;
630:   const speed = k.state === 'chase' ? 4.35 : 1.55;
631:   k.speed = damp(k.speed, speed, 2.4, dt);
632:   if (dist > 1.65) this._moveWithCollision(k.pos, Math.sin(k.yaw) * k.speed * dt, Math.cos(k.yaw) * k.speed * dt, 0.4);
633:   poseHumanoid(k.rig, this.time, k.speed, { idle: false });
634:   k.alertGlow.material.opacity = k.state === 'chase' ? 0.8 : 0.25;
635:   k.alertLight.intensity = k.state === 'chase' ? 6 : 2;
636:   k.lungeCD = Math.max(0, k.lungeCD - dt);
637:   if (dist < 1.8 && k.lungeCD <= 0) {
638:     k.lungeCD = 1.35;
639:     this._hurt(18);
640:   }
641: };
