643: Act1.prototype.update = function (dt) {
644:   if (this.ended) return;
645:   this.time += dt;
646:   this.invuln = Math.max(0, this.invuln - dt);
647:   this.dodgeCD = Math.max(0, this.dodgeCD - dt);
648:   this.dodgeT = Math.max(0, this.dodgeT - dt);
649:   this.staminaDelay = Math.max(0, this.staminaDelay - dt);
650:   this.shake = Math.max(0, this.shake - dt);
651:   this.rain.update(dt, this.player.pos);
652:   this.fx.update(dt);
653:   this.game.input.look && (this.camYaw -= this.game.input.look.x);
654:   this.camPitch = clamp(this.camPitch - this.game.input.look.y, -0.08, 0.68);
655:   this.camYaw = dampAngle(this.camYaw, this.player.yaw, 0.22, dt);
656:   const input = this.game.input;
657:   const p = this.player;
658:   if (input.dodgePressed()) this._attack();
659:   const forward = new THREE.Vector3(Math.sin(this.camYaw), 0, Math.cos(this.camYaw));
660:   const right = new THREE.Vector3(forward.z, 0, -forward.x);
661:   const wish = forward.multiplyScalar(-input.move.y).addScaledVector(right, input.move.x);
662:   const moving = wish.lengthSq() > 0.01;
663:   if (moving) wish.normalize();
664:   const sprint = input.sprint && p.stam > 2 && moving && !input.crouch;
