242: export function poseHumanoid(rig, t, speed, opts = {}) {
243:   const { crouch = 0, idle = true, armOverride = null } = opts;
244:   const amp = clamp(speed / 7, 0, 1.15);
245:   const p = t * (6.4 + speed * 0.55);
246:   const s = Math.sin(p), c = Math.cos(p);
247: 
248:   rig.legL.hip.rotation.x = s * 0.72 * amp;
249:   rig.legR.hip.rotation.x = -s * 0.72 * amp;
250:   rig.legL.knee.rotation.x = Math.max(0, -Math.sin(p + 0.9)) * 1.0 * amp + crouch * 0.7;
251:   rig.legR.knee.rotation.x = Math.max(0, -Math.sin(p + 0.9 + Math.PI)) * 1.0 * amp + crouch * 0.7;
252: 
253:   if (!armOverride) {
254:     rig.armL.shoulder.rotation.x = -s * 0.62 * amp;
255:     rig.armR.shoulder.rotation.x = s * 0.62 * amp;
256:     rig.armL.shoulder.rotation.z = -0.12 - amp * 0.04;
257:     rig.armR.shoulder.rotation.z = 0.12 + amp * 0.04;
258:     rig.armL.elbow.rotation.x = -0.35 - amp * 0.35;
259:     rig.armR.elbow.rotation.x = -0.35 - amp * 0.35;
260:   }
261: 
262:   const bob = Math.abs(s) * 0.055 * amp;
263:   rig.hips.position.y = rig.baseHipY - crouch * 0.34 + (idle && amp < 0.05 ? Math.sin(t * 1.6) * 0.008 : bob);
264:   rig.hips.rotation.y = s * 0.07 * amp;
265:   rig.hips.rotation.z = c * 0.03 * amp;
266:   rig.head.rotation.y = -s * 0.05 * amp;
267: }
