import { createRequire } from 'node:module';
import { mkdir } from 'node:fs/promises';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = require('/home/runner/.local/share/omgithub-playwright/linux.json');
process.env.DISPLAY ||= ':' + (await import('node:fs')).readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', e => errors.push(`pageerror: ${e.message}`));
page.on('console', m => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
page.on('response', r => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`); });
try {
  const response = await page.goto('http://127.0.0.1:3002', { waitUntil: 'load' });
  if (!response?.ok()) throw new Error(`Load failed: ${response?.status()}`);
  await page.waitForFunction(() => !!window.__game);
  await page.locator('#btn-play').click();
  await page.locator('#story-screen:not(.hidden)').waitFor();
  await page.locator('#btn-continue').click();
  await page.waitForFunction(() => window.__game?.state === 'playing' && window.__game.actIndex === 1);
  await page.evaluate(() => window.__game.actComplete(1, { time: 30, damage: 2 }));
  await page.locator('#story-screen:not(.hidden)').waitFor();
  await page.locator('#btn-continue').click();
  await page.waitForFunction(() => window.__game?.state === 'playing' && window.__game.actIndex === 2);
  await page.evaluate(() => window.__game.actComplete(2, { time: 25, damage: 0 }));
  await page.locator('#story-screen:not(.hidden)').waitFor();
  await page.locator('#btn-continue').click();
  await page.waitForFunction(() => window.__game?.state === 'playing' && window.__game.actIndex === 3);
  await page.evaluate(() => {
    const a = window.__game.act;
    a.player.pos.set(0, 0, 1.3);
    a.player.yaw = Math.PI;
    a.boss.pos.set(0, 0, 0);
    a.boss.yaw = 0;
    a.boss.state = 'approach';
    a.boss.cooldown = 10;
  });
  await page.waitForTimeout(500);
  await mkdir('/tmp/opencode/captures', { recursive: true });
  await page.screenshot({ path: '/tmp/opencode/captures/latest-act3.jpg', type: 'jpeg', quality: 82 });
  await page.keyboard.press('j');
  await page.waitForTimeout(150);
  const hit = await page.evaluate(() => ({ hp: window.__game.act.boss.health, state: window.__game.state, health: window.__game.act.health }));
  if (hit.hp >= 180) throw new Error(`Attack did not hit boss: ${JSON.stringify(hit)}`);
  await page.evaluate(() => { window.__game.act.attackCooldown = 0; window.__game.act.boss.health = 18; window.__game.act.bossHealth = 18; window.__game.act.boss.state = 'approach'; });
  await page.keyboard.press('j');
  await page.waitForFunction(() => window.__game.state === 'win', { timeout: 3000 });
  console.log(JSON.stringify({ actFlow: '1→2→3→victory', hit, errors }, null, 2));
  if (errors.length) process.exitCode = 2;
} finally { await browser.close(); }

